// ═══ THROW EARLY — fail fast at service entry ═══

// (Avoid) WRONG: throw late — bad value travels deep before failing
public class TradeService {
    public TradeResult settle(String tradeId) {
        Trade trade = tradeRepo.findById(tradeId);     // returns null
        BigDecimal amount = trade.getAmount();           // NPE here! 3 levels deep!
        Account account = accountRepo.findByTrade(trade);// never reached
        return settlementEngine.process(account, amount);// never reached
        // NPE at line 3 — but the REAL problem is: tradeId was invalid at line 2!
        // Stack trace shows NPE in getAmount() — misleading!
    }
}

// (Recommended) CORRECT: throw early — validate immediately
public class TradeService {
    public TradeResult settle(String tradeId) {
        // THROW EARLY: validate at the ENTRY POINT
        if (tradeId == null || tradeId.isBlank()) {
            throw new IllegalArgumentException("tradeId must not be blank");
        }
        Trade trade = tradeRepo.findById(tradeId)
            .orElseThrow(() -> new TradeNotFoundException(tradeId));
        // Fails HERE with a CLEAR message — not 5 layers deep with NPE!

        return settlementEngine.process(trade);
    }
}

// ═══ CATCH LATE — at the layer with context ═══

// (Avoid) WRONG: catch too early — service catches and returns null
public class TradeService {
    public TradeResult settle(String tradeId) {
        try {
            return settlementEngine.process(tradeId);
        } catch (SettlementException e) {
            log.error("Settlement failed", e);
            return null;  // ← WRONG! Caller doesn't know WHY. Null propagates.
            // Controller: if (result == null) ??? — what HTTP status? What message?
        }
    }
}

// (Recommended) CORRECT: service throws, controller catches with context
public class TradeService {
    public TradeResult settle(String tradeId) {
        // Validate early:
        Trade trade = tradeRepo.findById(tradeId)
            .orElseThrow(() -> new TradeNotFoundException(tradeId));
        // Let exception propagate — DON'T catch here!
        return settlementEngine.process(trade);
    }
}

// Controller (boundary) catches LATE — has HTTP context:
@RestController
public class TradeController {
    @PostMapping("/trades/{id}/settle")
    public ResponseEntity<TradeResult> settle(@PathVariable String id) {
        TradeResult result = tradeService.settle(id);
        return ResponseEntity.ok(result);
        // If TradeNotFoundException → @ControllerAdvice → 404
        // If SettlementException → @ControllerAdvice → 500
        // Controller doesn't even need try-catch! Global handler catches LATE.
    }
}

// ═══ CLEAN LAYERING ═══
// Repository: throws DataAccessException (Spring wraps JDBC)
// Service:    validates early, throws domain exceptions, does NOT catch
// Controller: catches late (via @ControllerAdvice), maps to HTTP response
// Kafka:      catches late, sends to DLQ or retries
// Batch:      catches late, logs + alerts + skips record
