// ─── File: test/ThrowEarlyCatchLateTest.java ───
package com.bank.layering;

import com.bank.layering.exception.*;
import com.bank.layering.service.SettlementService;
import org.junit.jupiter.api.Test;
import static org.assertj.core.api.Assertions.*;

class ThrowEarlyCatchLateTest {

    SettlementService service = new SettlementService();

    // THROW EARLY: blank input → immediate clear error
    @Test
    void throwEarly_blankInput() {
        assertThatThrownBy(() -> service.settle(""))
            .isInstanceOf(IllegalArgumentException.class)
            .hasMessageContaining("required");
    }

    // THROW EARLY: not found → clear domain exception
    @Test
    void throwEarly_notFound() {
        assertThatThrownBy(() -> service.settle("TRD-999"))
            .isInstanceOf(TradeNotFoundException.class)
            .hasMessageContaining("TRD-999");
        // NOT a NullPointerException 5 layers deep! Clear message at service entry.
    }

    // THROW EARLY: business rule violated
    @Test
    void throwEarly_marginExceeded() {
        assertThatThrownBy(() -> service.settle("TRD-002"))  // 5M > 1M max
            .isInstanceOf(InsufficientMarginException.class)
            .hasMessageContaining("5000000");
    }

    // CATCH LATE: controller/boundary maps to HTTP response
    @Test
    void catchLate_controllerMapsResponse() {
        // In real app: @ControllerAdvice catches at boundary
        // TradeNotFoundException → 404
        // InsufficientMarginException → 400
        // IllegalArgumentException → 400
        // Service has ZERO try-catch. Controller/GlobalHandler catches LATE.
        String result = service.settle("TRD-001");
        assertThat(result).contains("SETTLED");
    }
}
